var n=`0562-lagman`;var i=`world-0562`;var o=`UZ`;var a=`central-asia`;var l=4;var r=76;var s={en:`Lagman`,ua:`Лагман`};var g={en:`A traditional dish from Uzbekistan, centered on all-purpose flour, chicken egg, beef chuck, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: пшеничне борошно універсальне, куряче яйце, яловича лопатка, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,400,`g`],[`chicken-egg`,1,`pcs`],[`water`,160,`ml`],[`table-salt`,5,`g`]]},{en:`Roll and stretch the rested noodle dough into long strands, dusting lightly to prevent sticking.`,ua:`Розкачайте й обережно витягніть відпочиле тісто у довгі смуги локшини, злегка припудрюючи борошном.`,t:[`pressing`,`rolling-out-dough`],m:18,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 13 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 13 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:13,i:[[`beef-chuck`,480,`g`],[`yellow-onion`,190,`g`],[`red-bell-pepper`,190,`g`],[`tomato`,360,`g`],[`garlic`,4,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`beef-stock`,1e3,`ml`],[`ground-cumin`,4,`g`]]},{en:`Boil the stretched fresh noodles separately in abundant salted water until tender, then divide among bowls and ladle over the meat-and-vegetable broth.`,ua:`Відваріть витягнуту свіжу локшину окремо у великій кількості підсоленої води до м’якості, розкладіть у миски й залийте м’ясо-овочевою підливою.`,t:[`boiling`],m:7,i:[]}];var u={slug:n,id:i,country:`UZ`,region:a,servings:4,minutes:76,title:s,text:g,steps:d};export{o as country,u as default,i as id,r as minutes,a as region,l as servings,n as slug,d as steps,g as text,s as title};